namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She holds a PhD from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Analysis of algorithm complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm design and computational complexity. Previously worked at Google Research.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 301", Title = "Database Systems", Description = "Design and implementation of relational databases. SQL, normalization, query optimization, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez brings industry experience from Oracle and Microsoft to her teaching of database systems.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 1, Code = "CS 401", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and deep learning.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Alex Kim", InstructorBio = "Dr. Kim's research focuses on deep learning and natural language processing. He has published over 50 papers in top AI conferences.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research combines pure mathematics with applications in quantum computing.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 7, DepartmentId = 2, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park previously worked as a statistician at the CDC before joining academia.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Fri Lab 1:00–3:00 PM", InstructorName = "Dr. Lisa Zhang", InstructorBio = "Dr. Zhang is a theoretical physicist specializing in quantum electrodynamics.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop academic writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Anne Mitchell", InstructorBio = "Prof. Mitchell is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 11, DepartmentId = 4, Code = "ENG 205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Thomas Green", InstructorBio = "Dr. Green is a specialist in 20th-century American fiction and has written two books on the Harlem Renaissance.", IsFeatured = true, DepartmentName = "English" },
            new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the medieval period.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Karen White", InstructorBio = "Dr. White is an archaeologist and historian specializing in ancient Mediterranean civilizations.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 13, DepartmentId = 5, Code = "HIST 301", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Examines political, social, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Richard Adams", InstructorBio = "Dr. Adams has published extensively on 20th-century European political movements.", IsFeatured = false, DepartmentName = "History" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

